 public void PreviewArenaScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;RenderArenaDraftPreview(folder);VerifyArenaPointerInput();VerifyArenaDraft();VerifyArenaTcp();VerifyArenaIndependentChoices();File.WriteAllText(Path.Combine(folder,"arena-verification.txt"),"PASS: "+(checks-before)+" assertions; two private 30-pick drafts, supported class/neutral pool, exact arena deck validation, best-of-three rematches, loopback LAN and WPF draft previews.");}
 void RenderArenaDraftPreview(string folder){if(!VerificationRun.Visual)return;lanModePicker.SelectedItem=((Choice[])lanModePicker.ItemsSource).First(c=>c.Key=="arena");lanArenaMode=true;var draftPreview=new ArenaDraftSession(catalog,734,matchRules.Supports);lanArenaView=draftPreview.View(0);UpdateArenaDraftUi(lanArenaView);Render(Path.Combine(folder,"arena-class-choice.png"));draftPreview.Pick(0,lanArenaView.Session,lanArenaView.Revision,0);for(int i=0;i<8;i++){var state=draftPreview.View(0);draftPreview.Pick(0,state.Session,state.Revision,i%state.Choices.Length);}lanArenaView=draftPreview.View(0);UpdateArenaDraftUi(lanArenaView);Render(Path.Combine(folder,"arena-card-choice.png"));Check(arenaPickedPanel.Visibility==Visibility.Visible&&arenaPickedRows.Children.Count>0,"Arena draft shows a picked-card sidebar");var costs=arenaPickedRows.Children.OfType<TextBlock>().Select(row=>(int)row.Tag).ToArray();Check(costs.SequenceEqual(costs.OrderBy(cost=>cost)),"Arena picked-card sidebar sorts by mana cost");Check(arenaOfferButtons.All(b=>b.ActualWidth>70),"Arena choices fit the narrower three-column layout");ApplyMode(true);UpdateLayout();Render(Path.Combine(folder,"arena-card-choice-minimal.png"));Check(Width==392&&Height==300&&arenaOfferButtons.All(b=>b.ActualWidth>55&&b.ActualHeight>80),"Minimal Arena keeps three readable choices at fixed size");ApplyMode(false);SetArenaDraftLayout(false);lanArenaView=null;lanArenaMode=false;arenaStage.Visibility=System.Windows.Visibility.Collapsed;lanNotice.Visibility=System.Windows.Visibility.Visible;}
 void ArenaContentClick(PanelWindow window,int index,int child=0){var content=(StackPanel)((ScrollViewer)window.arenaOfferButtons[index].Content).Content;var source=(UIElement)content.Children[child];var down=new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount,System.Windows.Input.MouseButton.Left){RoutedEvent=System.Windows.Input.Mouse.PreviewMouseDownEvent};source.RaiseEvent(down);if(!down.Handled){down.RoutedEvent=System.Windows.Input.Mouse.MouseDownEvent;source.RaiseEvent(down);}var up=new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount,System.Windows.Input.MouseButton.Left){RoutedEvent=System.Windows.Input.Mouse.PreviewMouseUpEvent};source.RaiseEvent(up);if(!up.Handled){up.RoutedEvent=System.Windows.Input.Mouse.MouseUpEvent;source.RaiseEvent(up);}}
 void VerifyArenaPointerInput(){if(!VerificationRun.Visual)return;LeaveLan();lanModePicker.SelectedItem=((Choice[])lanModePicker.ItemsSource).First(c=>c.Key=="arena");lanArenaMode=lanIsHost=true;lanWaiting=false;lanArenaDraft=new ArenaDraftSession(catalog,734,matchRules.Supports);lanArenaView=lanArenaDraft.View(0);ShowPage("lan");UpdateArenaDraftUi(lanArenaView);UpdateLayout();ArenaContentClick(this,0);Check(lanArenaView.Phase=="cards","Routed pointer press on class text selects profession");int before=lanArenaView.Picks;ArenaContentClick(this,0);Check(lanArenaView.Picks==before+1,"Routed pointer press on card name selects a card");before=lanArenaView.Picks;ArenaContentClick(this,1,1);Check(lanArenaView.Picks==before+1,"Routed pointer press on effect text selects a card");ApplyMode(true);before=lanArenaView.Picks;ArenaContentClick(this,2,1);Check(lanArenaView.Picks==before+1,"Minimal mode accepts effect-area pointer selection");ApplyMode(false);var viewer=(ScrollViewer)arenaOfferButtons[0].Content;var body=(StackPanel)viewer.Content;((TextBlock)body.Children[1]).Text=String.Join("\n",Enumerable.Repeat("长效果说明，用于验证滚动条",100));UpdateLayout();viewer.ScrollToVerticalOffset(20);UpdateLayout();Check(viewer.ScrollableHeight>0&&viewer.VerticalOffset>0,"Arena long effects remain scrollable");var thumb=FindArenaThumb(viewer);Check(thumb!=null,"Real ScrollViewer exposes its vertical scroll thumb");before=lanArenaView.Picks;thumb.RaiseEvent(new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,Environment.TickCount,System.Windows.Input.MouseButton.Left){RoutedEvent=System.Windows.Input.Mouse.MouseDownEvent});Check(lanArenaView.Picks==before,"Scrollbar press does not draft a card");thumb.ReleaseMouseCapture();arenaOfferButtons[1].RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(lanArenaView.Picks==before+1,"Keyboard/automation Click path still drafts one card");LeaveLan();}
 Thumb FindArenaThumb(DependencyObject root){for(int n=0;n<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);n++){var child=System.Windows.Media.VisualTreeHelper.GetChild(root,n);var thumb=child as Thumb;if(thumb!=null)return thumb;var found=FindArenaThumb(child);if(found!=null)return found;}return null;}
 void VerifyArenaDraft(){
  int totalOffers=0,legendaryOffers=0;bool grouped=true,unique=true,milestones=true,legal=true;var defaults=new ArenaDraftWeights();
  Check(defaults.CardWeight(catalog.Card("VAN_CS2_029"))==2.25&&defaults.CardWeight(catalog.Card("VAN_CS2_120"))==1,"Class spell bonuses multiply, neutral minions retain base weight");
  for(int seed=0;seed<90;seed++){var sample=new ArenaDraftSession(catalog,17000+seed,matchRules.Supports);var view=sample.View(0);sample.Pick(0,view.Session,view.Revision,seed%3);for(int pick=0;pick<30;pick++){view=sample.View(0);var choices=view.Choices.Select(catalog.Card).ToArray();string tier=ArenaDraftWeights.Tier(choices[0]);grouped&=choices.All(c=>ArenaDraftWeights.Tier(c)==tier);unique&=choices.Select(c=>c.Id).Distinct().Count()==3;legal&=choices.All(c=>c.CardClass=="NEUTRAL"||c.CardClass==view.ClassId);if(pick==0||pick==9||pick==19||pick==29)milestones&=tier!="COMMON";totalOffers++;if(tier=="LEGENDARY")legendaryOffers++;sample.Pick(0,view.Session,view.Revision,pick%3);}}
  Check(grouped&&unique&&legal,"2700 offers each contain three distinct cards of one rarity tier and allowed class");Check(milestones,"Picks 1, 10, 20 and 30 offer Rare or better");Check(legendaryOffers>0&&legendaryOffers<totalOffers*.05,"Legendary offers remain rare rather than tracking legendary card count in the pool");
  bool badWeight=false;try{new ArenaDraftSession(catalog,1,matchRules.Supports,new ArenaDraftWeights{Legendary=Double.NaN});}catch(ArgumentException){badWeight=true;}Check(badWeight,"Reject invalid configurable draft weights");
  var draftSession=new ArenaDraftSession(catalog,8042,matchRules.Supports);var host=draftSession.View(0);var guest=draftSession.View(1);Check(host.Phase=="class"&&guest.Phase=="class"&&host.Choices.Length==3&&host.Choices.Distinct().Count()==3&&guest.Choices.Length==3&&guest.Choices.Distinct().Count()==3,"Arena randomly offers three distinct classes per seat");
  draftSession.Pick(0,host.Session,host.Revision,0);host=draftSession.View(0);Check(host.Phase=="cards"&&host.Choices.Length==3&&host.Choices.Distinct().Count()==3&&host.Choices.All(id=>{var c=catalog.Card(id);return c.CardClass=="NEUTRAL"||c.CardClass==host.ClassId;}),"Arena card offers contain only neutral or selected-class cards");string selected=host.Choices[0];draftSession.Pick(0,host.Session,host.Revision,0);host=draftSession.View(0);Check(host.PickedCards.Length==1&&host.PickedCards[0]==selected,"Arena private draft view exposes only that seat's picked cards");bool stale=false;try{draftSession.Pick(0,host.Session,host.Revision-1,0);}catch(InvalidOperationException){stale=true;}Check(stale,"Arena draft rejects stale pick revisions");
   for(int seat=0;seat<2;seat++){if(seat==1){var state=draftSession.View(seat);draftSession.Pick(seat,state.Session,state.Revision,0);}for(int i=draftSession.View(seat).Picks;i<ArenaDraftSession.DraftSize;i++){var state=draftSession.View(seat);draftSession.Pick(seat,state.Session,state.Revision,i%state.Choices.Length);}}
  var first=draftSession.Deck(0);var second=draftSession.Deck(1);Check(first.Count==30&&second.Count==30&&draftSession.View(0).Complete&&draftSession.View(1).Complete,"Arena drafts produce exactly 30 cards for both players");Check(first.Cards.Keys.All(id=>{var c=catalog.Card(id);return c.CardClass=="NEUTRAL"||c.CardClass==first.ClassId;}),"Arena deck validation rejects off-class cards");
  var repeated=first.Copy();repeated.Cards.Clear();string repeatId=catalog.Deckable(catalog.Pool("classic-2014")).First(c=>(c.CardClass=="NEUTRAL"||c.CardClass==first.ClassId)&&matchRules.Supports(c)).Id;repeated.Cards[repeatId]=30;ArenaDraftSession.Validate(catalog,repeated,true);Check(repeated.Count==30,"Arena permits repeated copies while enforcing the 30-card deck size");bool incomplete=false;repeated.Cards[repeatId]=29;try{ArenaDraftSession.Validate(catalog,repeated,true);}catch(InvalidDataException){incomplete=true;}Check(incomplete,"Arena rejects decks that are not exactly 30 cards");
 }
 void VerifyArenaTcp(){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);try{
   lanPort.Text=FreeLanPort().ToString();lanModePicker.SelectedItem=((Choice[])lanModePicker.ItemsSource).First(c=>c.Key=="arena");BeginLan(true);guest.lanModePicker.SelectedItem=((Choice[])guest.lanModePicker.ItemsSource).First(c=>c.Key=="arena");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanArenaDraft!=null&&guest.lanArenaView!=null,"Arena peers complete LAN handshake and receive private offers");Check(!lanReady&&!guest.lanReady&&match==null&&guest.match==null,"Arena drafting happens after connection and before any match starts");
   ArenaContentClick(this,0);ArenaContentClick(guest,0);var waitingDraft=guest.lanArenaView;guest.ReceiveLan(new LanMessage{Kind="arena-draft",ArenaDraft=waitingDraft});Check(guest.lanWaiting,"Opponent progress refresh cannot acknowledge our still-pending draft choice");PumpLan(()=>!guest.lanWaiting&&guest.lanArenaView.Phase=="cards","Both players select one of three classes");for(int i=0;i<ArenaDraftSession.DraftSize;i++){ArenaContentClick(this,i%3,i%2);ArenaContentClick(guest,(i+1)%3,i%2);if(i<ArenaDraftSession.DraftSize-1)PumpLan(()=>!guest.lanWaiting&&guest.lanArenaView.Picks==i+1,"Private Arena card choice "+(i+1)+" synchronizes");}
   PumpLan(()=>lanReady&&guest.lanReady&&match!=null&&guest.match!=null,"Both completed drafts start an Arena match");Check(match.Mode.Id=="arena"&&guest.match.Mode.Id=="arena","Arena match mode synchronizes across LAN");Check(lanArenaDraft.Deck(0).PoolId==ArenaDraftSession.CurrentPool(catalog).Id&&lanArenaDraft.Deck(1).PoolId==ArenaDraftSession.CurrentPool(catalog).Id,"Both network drafts use the current open pool");Check(lanAuthority.Game.Players.All(p=>p.Deck.Count+p.Hand.Count==30),"Arena match starts with both drafted 30-card decks");Check(lanAuthority.ArenaGameNumber==1&&lanAuthority.ArenaScoreLabel().StartsWith("0 - 0"),"Arena series begins as a best-of-three");guest.lanWaiting=true;guest.lanReady=false;guest.ReceiveLan(lanAuthority.Snapshot());Check(!guest.lanWaiting&&guest.lanArenaView==null&&guest.arenaStage.Visibility==Visibility.Collapsed,"Initial match state clears draft waiting and retires draft UI without a command ReplyId");Check(CanMulliganInput()&&guest.CanMulliganInput(),"Both Arena players can act during opening mulligan");CheckMulliganCardClick(this,"Host Arena opening cards are clickable");CheckMulliganCardClick(guest,"Guest Arena opening cards are clickable");turnClockTimer.Stop();string previousVisualSession=match.VisualSession;FinishArenaGameWithFireball(guest,0);System.Threading.Thread.Sleep(1900);var boundary=lanAuthority.Execute(0,new LanCommand{Kind="end",Session=lanAuthority.Session,Revision=lanAuthority.Revision});Check(!boundary.Success&&lanAuthority.ArenaGameNumber==2,"Command at rematch boundary starts the next authority game and rejects stale action");lanRevision=lanAuthority.Revision;lanAuthority.AcknowledgeLog(previousVisualSession,999);Check(lanAuthority.Snapshot().State.LogStart==0,"Previous-game log acknowledgement cannot skip new-game history");PublishLan(boundary);Check(Object.ReferenceEquals(match,lanAuthority.Game)&&matchViewSeat==0&&!match.MulliganComplete,"Host adopts a replacement authority game before publishing");turnClockTimer.Start();PumpLan(()=>lanAuthority.ArenaGameNumber==2&&guest.match!=null&&!guest.match.MulliganComplete,"Second Arena game resets both match states");Check(lanAuthority.ArenaWins1==1&&guest.lanArenaWins1==1,"Arena first-game score synchronizes to both players");FinishArenaGameWithFireball(guest,0);PumpLan(()=>lanAuthority.ArenaSeriesWinner==1&&guest.lanArenaSeriesWinner==1,"Two wins finish the best-of-three");System.Threading.Thread.Sleep(1900);Check(lanAuthority.ArenaGameNumber==2&&lanAuthority.ArenaSeriesWinner==1,"Finished Arena series does not start a third game");
  }finally{turnClockTimer.Start();guest.LeaveLan();guest.Close();LeaveLan();}}
 void VerifyArenaIndependentChoices(){if(!VerificationRun.Network)return;for(int leaderSeat=0;leaderSeat<2;leaderSeat++){LeaveLan();var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{
  lanPort.Text=FreeLanPort().ToString();lanModePicker.SelectedItem=((Choice[])lanModePicker.ItemsSource).First(c=>c.Key=="arena");BeginLan(true);guest.lanModePicker.SelectedItem=((Choice[])guest.lanModePicker.ItemsSource).First(c=>c.Key=="arena");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanArenaDraft!=null&&guest.lanArenaView!=null,"Independent draft peers connect");
  var leader=leaderSeat==0?this:guest;var follower=leaderSeat==0?guest:this;
  ArenaContentClick(leader,0);PumpLan(()=>!leader.lanWaiting&&leader.lanArenaView.Phase=="cards","Leader selects class independently");
  for(int i=0;i<30;i++){int expected=i+1;ArenaContentClick(leader,i%3,i%2);PumpLan(()=>!leader.lanWaiting&&leader.lanArenaView.Picks==expected&&follower.lanArenaView.OpponentPicks==expected,"Leader draft progresses while other player stays idle");Check(!follower.lanWaiting&&follower.arenaOfferButtons.All(b=>b.IsEnabled),"Opponent progress leaves idle player's choices enabled");}
  Check(leader.lanArenaView.Complete&&!lanReady&&!guest.lanReady&&follower.lanArenaView.Phase=="class","Leader waits at 30 without starting or blocking other player's class choice");
  ArenaContentClick(follower,1);PumpLan(()=>!follower.lanWaiting&&follower.lanArenaView.Phase=="cards","Idle player can select class after opponent completes");
  for(int i=0;i<30;i++){int expected=i+1;Check(follower.arenaOfferButtons.All(b=>b.IsEnabled),"Follower choices stay enabled after opponent completes");ArenaContentClick(follower,(i+1)%3,i%2);if(i<29)PumpLan(()=>!follower.lanWaiting&&follower.lanArenaView.Picks==expected,"Follower continues drafting after opponent completes");}
  PumpLan(()=>lanReady&&guest.lanReady&&match!=null&&guest.match!=null,"Asymmetric drafts both reach opening hand");Check(CanMulliganInput()&&guest.CanMulliganInput(),"Both asymmetric draft seats can mulligan");CheckMulliganCardClick(this,"Asymmetric host opening cards respond");CheckMulliganCardClick(guest,"Asymmetric guest opening cards respond");
 }finally{guest.LeaveLan();guest.Close();LeaveLan();}}}
 void CheckMulliganCardClick(PanelWindow window,string description){var root=window.livePanel.Children.OfType<ScrollViewer>().First(child=>Grid.GetRow(child)==6);var overlay=(Grid)root.Content;var cards=(StackPanel)overlay.Children[0];var button=cards.Children.OfType<Button>().First();int id=(int)button.Tag;Check(button.IsEnabled,"Opening mulligan card is enabled");button.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(window.selectedMulligan.Contains(id),description);}
 void FinishArenaGameWithFireball(PanelWindow guest,int loser){DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match!=null&&guest.match.Players[0].MulliganDone,"Arena host confirms opening hand");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&guest.match.MulliganComplete,"Arena mulligan completes for both players");int winner=1-loser;var game=lanAuthority.Game;game.Players[loser].Health=1;game.Players[winner].Mana=game.Players[winner].MaxMana=10;game.Active=winner;int fireball=Inject(game,"CS2_029",winner);PublishLan();PumpLan(()=>guest.match.Active==winner&&guest.match.Players[winner].Hand.Any(h=>h.Id==fireball),"Arena test lethal reaches guest hand");guest.BeginCard(fireball);guest.ClickMatchTarget(new MatchTarget(loser));PumpLan(()=>lanAuthority.ArenaWins1==2&&guest.lanArenaWins1==2||lanAuthority.ArenaWins0==2&&guest.lanArenaWins0==2||guest.match!=null&&guest.match.Finished,"Arena game result synchronizes");Check(game.Finished&&game.Winner==winner,"Arena game ends through ordinary card rules");}
